/* Embedded image data — keeps the whole site to 3 files, no separate assets folder to upload. */
const IMAGES = {
  'robotics-build-1': 'data:image/jpeg;base64,',
  'robotics-build-2': 'data:image/jpeg;base64,',
  'microbit-two-boys-heart': 'data:image/jpeg;base64,',
  'ai-teachable-machine-1': 'data:image/jpeg;base64,',
  'ai-teachable-machine-2': 'data:image/jpeg;base64,',
  'group-tablet-maze': 'data:image/jpeg;base64,',
  'microbit-led-girl': 'data:image/jpeg;base64,',
  'microbit-four-boys-whiteboard': 'data:image/jpeg;base64,',
  'cs-tablet-scratch': 'data:image/jpeg;base64,',
  'microbit-girls-team': 'data:image/jpeg;base64,',
  'microbit-girl-stem-notebook': 'data:image/jpeg;base64,',
  'microbit-two-girls-tablet': 'data:image/jpeg;base64,',
  'microbit-girl-laptop-green': 'data:image/jpeg;base64,'
};

document.addEventListener('DOMContentLoaded', () => {

  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* ============ PRELOADER ============ */
  const preloader = document.getElementById('preloader');
  const preloaderFill = document.getElementById('preloaderFill');
  let progress = 0;
  const loadTimer = setInterval(() => {
    progress += Math.random() * 18;
    if (progress >= 100) {
      progress = 100;
      clearInterval(loadTimer);
      preloaderFill.style.width = '100%';
      setTimeout(() => {
        preloader.classList.add('is-done');
        document.body.style.overflow = '';
      }, 250);
    } else {
      preloaderFill.style.width = progress + '%';
    }
  }, 120);
  document.body.style.overflow = 'hidden';
  window.addEventListener('load', () => {
    progress = 100;
    preloaderFill.style.width = '100%';
  });

  /* ============ CUSTOM CURSOR ============ */
  const cursorDot = document.getElementById('cursorDot');
  const cursorRing = document.getElementById('cursorRing');
  const isFinePointer = window.matchMedia('(pointer:fine)').matches;

  if (isFinePointer && !reducedMotion) {
    let mouseX = 0, mouseY = 0, ringX = 0, ringY = 0;
    window.addEventListener('mousemove', (e) => {
      mouseX = e.clientX; mouseY = e.clientY;
      cursorDot.style.transform = `translate(${mouseX}px, ${mouseY}px) translate(-50%,-50%)`;
    });
    function animateRing() {
      ringX += (mouseX - ringX) * 0.18;
      ringY += (mouseY - ringY) * 0.18;
      cursorRing.style.transform = `translate(${ringX}px, ${ringY}px) translate(-50%,-50%)`;
      requestAnimationFrame(animateRing);
    }
    animateRing();

    document.addEventListener('mouseover', (e) => {
      if (e.target.closest('[data-hover], a, button, .tilt')) {
        cursorRing.classList.add('is-active');
      }
    });
    document.addEventListener('mouseout', (e) => {
      if (e.target.closest('[data-hover], a, button, .tilt')) {
        cursorRing.classList.remove('is-active');
      }
    });
  } else {
    cursorDot.style.display = 'none';
    cursorRing.style.display = 'none';
  }

  /* ============ SCROLL PROGRESS + PARALLAX (rAF loop) ============ */
  const scrollProgress = document.getElementById('scrollProgress');
  const heroImg = document.getElementById('heroImg');
  const roboticsParallax = document.getElementById('roboticsParallax');
  const aboutParallax = document.getElementById('aboutParallax');

  function onScroll() {
    const scrollTop = window.scrollY;
    const docHeight = document.documentElement.scrollHeight - window.innerHeight;
    const pct = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;
    scrollProgress.style.width = pct + '%';

    if (!reducedMotion) {
      if (heroImg) heroImg.style.transform = `translateY(${scrollTop * 0.18}px)`;
      if (roboticsParallax) {
        const rect = roboticsParallax.parentElement.getBoundingClientRect();
        if (rect.top < window.innerHeight && rect.bottom > 0) {
          const shift = (rect.top) * 0.12;
          roboticsParallax.style.transform = `translateY(${shift}px)`;
        }
      }
      if (aboutParallax) {
        const rect = aboutParallax.getBoundingClientRect();
        if (rect.top < window.innerHeight && rect.bottom > 0) {
          const shift = (rect.top - window.innerHeight / 2) * 0.06;
          aboutParallax.style.transform = `translateY(${shift}px) scale(1.08)`;
        }
      }
    }

    backToTop.classList.toggle('is-visible', scrollTop > 500);
  }
  window.addEventListener('scroll', () => requestAnimationFrame(onScroll), { passive: true });
  onScroll();

  /* ============ MOBILE NAV ============ */
  const navToggle = document.getElementById('navToggle');
  const navMenu = document.getElementById('primaryMenu');
  navToggle.addEventListener('click', () => {
    const isOpen = navMenu.classList.toggle('is-open');
    navToggle.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
  });
  navMenu.querySelectorAll('.nav-link, .nav-cta').forEach(link => {
    link.addEventListener('click', () => {
      navMenu.classList.remove('is-open');
      navToggle.setAttribute('aria-expanded', 'false');
    });
  });

  /* ============ SCROLL REVEAL ============ */
  const revealEls = document.querySelectorAll('.reveal, .reveal-up, .reveal-mask, .why-card');
  if ('IntersectionObserver' in window) {
    const io = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
          io.unobserve(entry.target);
        }
      });
    }, { threshold: 0.15, rootMargin: '0px 0px -60px 0px' });
    revealEls.forEach(el => io.observe(el));
  } else {
    revealEls.forEach(el => el.classList.add('is-visible'));
  }

  /* ============ TILT CARDS ============ */
  if (!reducedMotion && isFinePointer) {
    document.querySelectorAll('.tilt').forEach(card => {
      card.addEventListener('mousemove', (e) => {
        const rect = card.getBoundingClientRect();
        const x = (e.clientX - rect.left) / rect.width - 0.5;
        const y = (e.clientY - rect.top) / rect.height - 0.5;
        card.style.transform = `perspective(700px) rotateX(${(-y * 7).toFixed(2)}deg) rotateY(${(x * 7).toFixed(2)}deg) translateY(-4px)`;
      });
      card.addEventListener('mouseleave', () => {
        card.style.transform = 'perspective(700px) rotateX(0) rotateY(0) translateY(0)';
      });
    });
  }

  /* ============ BACK TO TOP ============ */
  const backToTop = document.getElementById('backToTop');
  backToTop.hidden = false;
  backToTop.addEventListener('click', () => window.scrollTo({ top: 0, behavior: 'smooth' }));

  /* ============ STEM INTERACTIVE CARDS ============ */
  const stemDetails = {
    science: 'Science at St. Mary\u2019s means asking questions, running experiments, and using evidence to explain how the world works \u2014 the foundation every STEM project builds on.',
    technology: 'Technology lessons introduce students to the digital tools, software, and devices used to design, build, and share their ideas.',
    engineering: 'Engineering challenges students to design a solution, build a working version, test it, and improve it \u2014 exactly the cycle used in the Robotics Club.',
    mathematics: 'Mathematics gives students the tools to measure, calculate, and reason clearly \u2014 skills that sit behind every STEM and coding project.'
  };
  const stemCards = document.querySelectorAll('.stem-card');
  const stemDetail = document.getElementById('stemDetail');
  const stemDetailText = document.getElementById('stemDetailText');
  stemCards.forEach(card => {
    card.addEventListener('click', () => {
      const key = card.dataset.stem;
      const alreadyOpen = card.getAttribute('aria-expanded') === 'true';
      stemCards.forEach(c => c.setAttribute('aria-expanded', 'false'));
      if (alreadyOpen) {
        stemDetail.hidden = true;
      } else {
        card.setAttribute('aria-expanded', 'true');
        stemDetailText.textContent = stemDetails[key] || '';
        stemDetail.hidden = false;
        stemDetail.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }
    });
  });

  /* ============ PROJECT DATA ============ */
  const projects = [
    { title: 'Autonomous Line-Following Robot', category: 'Robotics', img: IMAGES['robotics-build-1'], alt: 'Students wiring the sensors and chassis of a small robot at a classroom table.', desc: 'A concept robotics build exploring sensor wiring and chassis assembly, aimed at a future line-following challenge.' },
    { title: 'Smart Home Automation Model', category: 'Electronics', img: IMAGES['microbit-two-boys-heart'], alt: 'Two students holding tablets showing a micro:bit LED heart design they programmed.', desc: 'A concept project using a micro:bit and its LED display to represent the idea of an automated home system.' },
    { title: 'Sensor & Circuit Prototype', category: 'Arduino', img: IMAGES['robotics-build-2'], alt: 'Three students working together with a laptop and wired sensor components.', desc: 'An example project connecting a sensor to a microcontroller as a first step toward reading and displaying live data.' },
    { title: 'AI Emotion Recognition Demo', category: 'Programming', img: IMAGES['ai-teachable-machine-1'], alt: 'A tablet screen running an AI image-recognition tool, testing a model.', desc: 'A concept AI project built with a teachable-machine style tool, training a simple image-recognition model from scratch.' },
    { title: 'Block-Coding Maze Challenge', category: 'Programming', img: IMAGES['group-tablet-maze'], alt: 'A group of students working together to solve a logic activity on a tablet.', desc: 'A collaborative example project where students use block-based code to solve a logic and pathfinding puzzle.' },
    { title: 'LED Matrix Animation', category: 'STEM', img: IMAGES['microbit-led-girl'], alt: 'A student working with a micro:bit LED matrix display on a tablet.', desc: 'A concept STEM project programming a micro:bit\u2019s LED matrix to display custom patterns and animations.' },
    { title: 'Team Coding Showcase', category: 'Robotics', img: IMAGES['microbit-four-boys-whiteboard'], alt: 'Four students holding tablets showing their MakeCode micro:bit projects.', desc: 'An example showcase of a MakeCode micro:bit activity, developed and presented as a team.' },
    { title: 'Interface Design Concept', category: 'Web Development', img: IMAGES['cs-tablet-scratch'], alt: 'A student navigating a block-based coding interface on a tablet.', desc: 'An early concept exploration of digital interface design \u2014 a first step on the path toward web development skills.' }
  ];

  const projectGrid = document.getElementById('projectGrid');
  projectGrid.innerHTML = projects.map((p, i) => `
    <article class="project-card reveal-item" data-category="${p.category}">
      <div class="project-card-img">
        <img src="${p.img}" alt="${p.alt}" loading="lazy">
        <span class="project-card-cat">${p.category}</span>
      </div>
      <div class="project-card-body">
        <h3>${p.title}</h3>
        <p>${p.desc}</p>
        <button class="project-view-btn" data-index="${i}" data-hover>View Project</button>
      </div>
    </article>
  `).join('');

  if ('IntersectionObserver' in window) {
    const projIo = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) { entry.target.classList.add('is-visible'); projIo.unobserve(entry.target); }
      });
    }, { threshold: 0.1 });
    document.querySelectorAll('.project-card.reveal-item').forEach(el => projIo.observe(el));
  } else {
    document.querySelectorAll('.project-card.reveal-item').forEach(el => el.classList.add('is-visible'));
  }

  /* ============ PROJECT FILTERING ============ */
  const filterBtns = document.querySelectorAll('.filter-btn');
  filterBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      filterBtns.forEach(b => b.classList.remove('is-active'));
      btn.classList.add('is-active');
      const filter = btn.dataset.filter;
      document.querySelectorAll('.project-card').forEach(card => {
        const match = filter === 'all' || card.dataset.category === filter;
        card.classList.toggle('is-hidden', !match);
      });
    });
  });

  /* ============ MODAL ============ */
  const modalBackdrop = document.getElementById('modalBackdrop');
  const modalImage = document.getElementById('modalImage');
  const modalCategory = document.getElementById('modalCategory');
  const modalTitle = document.getElementById('modalTitle');
  const modalDesc = document.getElementById('modalDesc');
  const modalClose = document.getElementById('modalClose');

  function openModal({ title, category, img, alt, desc }) {
    modalImage.src = img;
    modalImage.alt = alt;
    modalCategory.textContent = category;
    modalTitle.textContent = title;
    modalDesc.textContent = desc;
    modalBackdrop.hidden = false;
    document.body.style.overflow = 'hidden';
    modalClose.focus();
  }
  function closeModal() {
    modalBackdrop.hidden = true;
    document.body.style.overflow = '';
  }
  projectGrid.addEventListener('click', (e) => {
    const btn = e.target.closest('.project-view-btn');
    if (!btn) return;
    openModal(projects[Number(btn.dataset.index)]);
  });
  modalClose.addEventListener('click', closeModal);
  modalBackdrop.addEventListener('click', (e) => { if (e.target === modalBackdrop) closeModal(); });
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && !modalBackdrop.hidden) closeModal(); });

  /* ============ ACHIEVEMENTS TIMELINE ============ */
  const achievements = [
    { title: 'Robotics Competition', desc: 'Achievement details coming soon.', img: IMAGES['microbit-four-boys-whiteboard'], alt: 'Four students holding tablets showing their micro:bit MakeCode projects in front of a whiteboard.' },
    { title: 'STEM Exhibition', desc: 'Student projects and results will be showcased here.', img: IMAGES['microbit-girls-team'], alt: 'A team of students smiling while presenting their coding project on a tablet.' },
    { title: 'Science Fair', desc: 'Details will be added as events are confirmed.', img: IMAGES['microbit-girl-stem-notebook'], alt: 'A student working through a STEM activity notebook alongside a coding project.' },
    { title: 'Coding Competition', desc: 'Results and highlights will appear here.', img: IMAGES['ai-teachable-machine-2'], alt: 'A laptop screen running an AI image-classification model built by students.' },
    { title: 'Technology Showcase', desc: 'Achievement details coming soon.', img: IMAGES['microbit-two-girls-tablet'], alt: 'Two students reviewing a coding project together on a tablet.' },
    { title: 'Student Innovation Projects', desc: 'Student projects and results will be showcased here.', img: IMAGES['microbit-girl-laptop-green'], alt: 'A student working on a coding project using a laptop.' }
  ];
  const timelineList = document.getElementById('timelineList');
  timelineList.innerHTML = achievements.map(a => `
    <li class="timeline-item reveal">
      <div class="timeline-body">
        <span class="badge badge-outline">Placeholder</span>
        <h3>${a.title}</h3>
        <p>${a.desc}</p>
      </div>
      <div class="timeline-media"><img src="${a.img}" alt="${a.alt}" loading="lazy"></div>
      <div class="timeline-spacer"></div>
    </li>
  `).join('');
  if ('IntersectionObserver' in window) {
    const tIo = new IntersectionObserver((entries) => {
      entries.forEach(entry => { if (entry.isIntersecting) { entry.target.classList.add('is-visible'); tIo.unobserve(entry.target); } });
    }, { threshold: 0.15 });
    document.querySelectorAll('.timeline-item.reveal').forEach(el => tIo.observe(el));
  } else {
    document.querySelectorAll('.timeline-item.reveal').forEach(el => el.classList.add('is-visible'));
  }

  /* ============ EVENTS ============ */
  const events = [
    { name: 'STEM Innovation Day', date: 'Date to be announced', location: 'St. Mary\u2019s Private High School', category: 'STEM', desc: 'An example event bringing together hands-on STEM activities and student project displays.' },
    { name: 'Robotics Workshop', date: 'Date to be announced', location: 'St. Mary\u2019s Private High School', category: 'Robotics', desc: 'An example workshop session for building and programming with the Robotics Club.' },
    { name: 'Coding Challenge', date: 'Date to be announced', location: 'St. Mary\u2019s Private High School', category: 'Computer Science', desc: 'An example friendly coding challenge for students to practice programming skills.' },
    { name: 'Technology Showcase', date: 'Date to be announced', location: 'St. Mary\u2019s Private High School', category: 'Technology', desc: 'An example showcase where students present their computer science, STEM, and robotics projects.' }
  ];
  const eventGrid = document.getElementById('eventGrid');
  eventGrid.innerHTML = events.map((ev, i) => `
    <article class="event-card">
      <span class="event-date">${ev.date}</span>
      <h3>${ev.name}</h3>
      <p class="event-meta">${ev.location} &middot; ${ev.category}</p>
      <p class="event-desc">${ev.desc}</p>
      <button class="event-learn-more" data-index="${i}" data-hover>Learn More \u2192</button>
    </article>
  `).join('');
  eventGrid.addEventListener('click', (e) => {
    const btn = e.target.closest('.event-learn-more');
    if (!btn) return;
    const ev = events[Number(btn.dataset.index)];
    openModal({
      title: ev.name, category: ev.category,
      img: IMAGES['microbit-girls-team'],
      alt: 'Students at St. Mary\u2019s taking part in a technology activity.',
      desc: `${ev.desc} Location: ${ev.location}. ${ev.date} \u2014 full details will be shared once confirmed.`
    });
  });

  /* ============ CONTACT FORM VALIDATION ============ */
  const form = document.getElementById('contact-form');
  const formSuccess = document.getElementById('formSuccess');
  function setError(input, message) {
    const row = input.closest('.form-row');
    const errorEl = row.querySelector('.form-error');
    row.classList.toggle('has-error', Boolean(message));
    errorEl.textContent = message || '';
  }
  function validateField(input) {
    if (input.hasAttribute('required') && !input.value.trim()) { setError(input, 'This field is required.'); return false; }
    if (input.type === 'email' && input.value.trim()) {
      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailPattern.test(input.value.trim())) { setError(input, 'Please enter a valid email address.'); return false; }
    }
    setError(input, '');
    return true;
  }
  form.querySelectorAll('input, textarea').forEach(input => input.addEventListener('blur', () => validateField(input)));
  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const fields = form.querySelectorAll('input[required], textarea[required]');
    let allValid = true;
    fields.forEach(field => { if (!validateField(field)) allValid = false; });
    if (allValid) {
      formSuccess.hidden = false;
      form.reset();
      formSuccess.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      setTimeout(() => { formSuccess.hidden = true; }, 6000);
    }
  });

});
